mapper.delete:
DELETE FROM wiki_asset_relation
WHERE source_asset_id = #{assetId}
   OR (target_asset_id = #{assetId} AND relation_type IN ('SOURCE', 'ANALYSIS_CITATION'))

mapper.select:
SELECT asset_id, space_id, asset_name, asset_type
FROM wiki_asset
WHERE status = '0' AND COALESCE(tags, '') <> 'SYSTEM_INDEX'
AND space_id = #{spaceId}
ORDER BY asset_name, asset_id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM wiki_asset
WHERE status = '0' AND COALESCE(tags, '') <> 'SYSTEM_INDEX'
AND space_id = #{spaceId}

SELECT r.relation_id, r.source_asset_id, source.asset_name AS source_name, r.target_asset_id, COALESCE(target.asset_name, r.target_name) AS target_name, r.relation_type, r.source_position FROM wiki_asset_relation r JOIN wiki_asset source ON source.asset_id = r.source_asset_id AND source.status = '0' LEFT JOIN wiki_asset target ON target.asset_id = r.target_asset_id AND target.status = '0' WHERE
r.target_asset_id = #{assetId} r.source_asset_id = #{assetId} (r.source_asset_id = #{assetId} OR r.target_asset_id = #{assetId})
ORDER BY r.source_position, r.relation_id LIMIT #{limit} OFFSET #{offset}
